'Payment_Amounts_Help' => 'Ang Halagang Binayaran ay nag-aayos ng balanse at nagbabawas ng Utang. Ang Natanggap na Halaga ay ang cash na iniabot: ginagamit lang ito para kalkulahin ang Sukli na ibabalik, at hindi nito binabago ang Utang.',

'Show_Tax_Desc' => 'Ang buwis na inilapat sa buong benta sa checkout, naka-print bilang sariling linya na "Buwis ng Order" sa mga kabuuan.',
'Show_Items_Tax_Desc' => 'Ang kabuuan ng sariling buwis ng bawat produkto, naka-print bilang linya na "Kabuuang Buwis ng mga Item". Kapag naka-enable, ipinapakita ang subtotal nang hindi kasama ang mga buwis na ito.',
'Show_Discount_Desc' => 'Ang diskwentong inilapat sa buong benta (kasama ang anumang diskwento mula sa points), naka-print bilang sariling linya sa mga kabuuan.',
'Show_Product_Discount_Desc' => 'Ang sariling diskwento ng bawat produkto, naka-print sa ilalim ng produktong iyon sa listahan ng mga item.',

'Receipt_Font_Family' => 'Font ng Resibo',
