'Warehouses_Tab_Help' => 'Pamahalaan ang iyong mga warehouse (tindahan/sangay). Bawat warehouse ay may sariling stock, at bawat dokumento — benta, pagbili, transfer, adjustment — ay itinatala laban sa isa sa mga ito.',
'Warehouse_Locations_Tab_Help' => 'Tukuyin ang mga lokasyon ng rack / shelf sa loob ng bawat warehouse (hal. Aisle 2 – Rack B). Italaga ang mga ito sa mga produkto para ipakita kung saan pisikal na nakatago ang mga item.',
