'Enable_Pos_Salesperson_Switch' => 'Palitan ang Salesperson Habang Nagche-checkout',
'Enable_Pos_Salesperson_Switch_Hint' => 'Magpakita ng salesperson picker sa POS screen para maitalaga ang benta sa ibang empleyado nang hindi nagla-logout. Naka-save sa invoice ang napiling salesperson at ginagamit sa mga ulat ng benta; hindi nagbabago ang aktibong POS session.',

'Wallet_Payment_Method_Missing' => 'Nawawala ang paraan ng pagbabayad na Wallet',
'Wallet_Payment_Method_Missing_Help' => 'Walang nahanap na paraan ng pagbabayad na eksaktong pinangalanang "Wallet". Itinutugma ang wallet tender ng POS ayon sa pangalang ito, kaya hindi makakapagbayad ang mga customer gamit ang kanilang wallet hangga\'t hindi ka nagdaragdag ng paraan ng pagbabayad na pinangalanang "Wallet" dito:',

'Show_Previous_Dues_Line' => 'Ipakita ang Linya ng Mga Nakaraang Utang',
'Show_Previous_Dues_Line_Desc' => 'Balanseng inutang ng customer bago ang bentang ito. Ipi-print lang kapag mas malaki ito sa zero.',
'Show_Net_Balance_Line' => 'Ipakita ang Linya ng Net na Balanse',
'Show_Net_Balance_Line_Desc' => 'Mga nakaraang utang kasama ang natitirang utang sa bentang ito. Ipi-print lang kapag mas malaki sa zero ang mga nakaraang utang.',

'QZ_Tray_Printer' => 'QZ Tray (printer sa computer na ito)',
'QZ_Printer_Name_Hint' => 'Ang pangalan ng printer gaya ng lumalabas sa computer na nagpapatakbo ng QZ Tray. Iwanang blangko para gamitin ang default na printer ng computer na iyon. I-click ang ⟳ para hanapin ang mga printer.',
'QZ_Not_Running' => 'Hindi tumatakbo ang QZ Tray sa computer na ito. I-install ito mula sa qz.io at panatilihin itong tumatakbo, pagkatapos ay payagan ang website na ito kapag nagtanong ang QZ.',
'Detect_Printers' => 'Hanapin ang mga printer',
'QZ_Download_Cert' => 'I-download ang certificate (override.crt)',
'QZ_Setup_Title' => 'Paano i-set up ang pag-print gamit ang QZ Tray (isang beses, sa bawat computer na nagpi-print ng label)',
'QZ_Step_Install' => '1. I-install ang QZ Tray sa computer na ito — i-download ito nang libre mula sa qz.io, pagkatapos ay simulan ito at hayaang tumatakbo (nasa system tray ito sa Windows o sa menu bar sa macOS).',
'QZ_Step_Connect' => '2. Ikonekta ang iyong label printer sa pamamagitan ng USB at tiyaking naka-install ito sa operating system (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners).',
'QZ_Step_Detect' => '3. I-click ang ⟳ button sa tabi ng "Pangalan ng printer" sa itaas para hanapin ang mga printer sa computer na ito, pagkatapos ay piliin ang iyong label printer. Iwanang blangko ang field para gamitin ang default na printer ng computer.',
'QZ_Step_Cert' => '4. Para mag-print nang walang permission popup, i-download ang certificate sa ibaba at kopyahin ito sa installation folder ng QZ Tray, na pinalitan ang pangalan sa override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Pagkatapos ay isara ang QZ Tray at simulan itong muli.',
'QZ_Step_Test' => '5. I-click ang "Mag-print ng test label" sa ibaba. Kung humingi ng pahintulot ang QZ Tray, i-click ang Allow — kapag naka-install ang certificate, hindi na ito magtatanong muli.',
'QZ_Step_Save' => '6. I-click ang Isumite para i-save ang mga setting na ito. Direktang magpi-print na sa printer na ito ang mga label mula sa Print Barcode page, nang walang print dialog ng browser.',
'QZ_Setup_Note' => 'Tumatakbo ang QZ Tray sa computer na ginagamit mo sa pag-browse, kaya gumagana ito kahit naka-host ang Stocky sa isang remote server. Kailangang naka-install ang QZ Tray sa bawat computer na nagpi-print ng label.',

// PWA settings tab — installable app identity
'PWA_Enabled' => 'I-enable ang installable na app',
'PWA_Enabled_Help' => 'Hinahayaan ang mga browser na mag-alok na i-install ang app na ito sa mga phone, tablet at desktop, at pinapanatiling naka-cache ang mga page para gumana offline. Ang pag-off nito ay nag-aalis ng install prompt saanman at nili-clear ang cache sa susunod na pagbisita.',
'PWA_Identity' => 'Pagkakakilanlan ng app',
