'PWA_Short_Name' => 'Maikling pangalan',
'PWA_Short_Name_Help' => 'Ipinapakita sa ilalim ng icon sa mga home screen, kung saan pinuputol ang mahahabang pangalan. Iwanang blangko para gamitin ang bahagi ng pangalan ng app bago ang "|".',
