'Label_Render_Mode' => 'Pag-render ng label',
'Label_Render_Mode_Hint' => 'Kung paano iginuguhit ang label. Ang Printer fonts ang pinakamabilis at nagbibigay ng pinakamalinaw na barcode, ngunit basic na Latin character lang ang napi-print gamit ang sariling typeface ng printer. Eksaktong ginagaya ng Preview image ang disenyo ng iyong label — ang napili mong font, anumang wika — gaya ng ginagawa ng dedikadong label software.',
'Render_Native' => 'Printer fonts (pinakamabilis)',
'Render_Raster' => 'Preview image (eksaktong disenyo)',
'Label_Width_Mm' => 'Lapad ng label (mm)',
'Label_Height_Mm' => 'Taas ng label (mm)',
'Label_Size_Hint' => 'Ang pisikal na laki ng isang sticker sa roll. Dapat eksaktong tumugma ito sa mga nakakargang label — ang maling laki ay nagpapahanap sa printer ng puwang sa maling lugar, kaya lalong lumalayo sa posisyon ang bawat label.',
'Calibrate_Labels' => 'I-calibrate ang mga label',
'Calibrate_Labels_Hint' => 'Nagpapasok ang printer ng ilang label para sukatin ang sticker at puwang. Patakbuhin nang isang beses pagkatapos magkarga ng bagong roll, o kapag lumilihis ang mga posisyon ng print.',
'Calibration_Sent' => 'Nagsimula ang calibration — magpapasok ang printer ng ilang blangkong label para sukatin ang mga ito. Kapag huminto ito, magpatakbo ng test print.',
'Label_Printer_Dpi' => 'Resolution ng printhead',
'Label_Printer_Dpi_Hint' => 'Karamihan sa mga label printer ay 203 dpi. Hindi sigurado? Gamitin ang button na "Alamin ang resolution" sa ibaba — ipi-print nito ang sagot.',
'Find_Resolution' => 'Alamin ang resolution',
'Find_Resolution_Hint' => 'Nagpi-print ng dalawang label, na may markang 203 at 300. Ang tama ay nagpapakita ng kumpletong parihaba sa sticker na may maliit at pantay na margin sa lahat ng apat na gilid; ang mali ay may nawawalang border o lumalampas sa susunod na sticker.',
'Dpi_Test_Sent' => 'Nagpi-print ang dalawang label, na may markang 203 at 300. Ang tama ay nagpapakita ng kumpletong parihaba na may maliit at pantay na margin sa lahat ng apat na gilid — itakda ang "Resolution ng printhead" sa numerong iyon at i-save.',
'Label_Offset_X' => 'Pahalang na offset (mm)',
'Label_Offset_X_Hint' => 'Inililipat ang print pagilid sa sticker. Gamitin kapag naputol ang teksto sa isang gilid — hal. 2.5 kapag nakagitna ang puting sticker sa mas malapad na backing paper. I-adjust nang 0.5 bawat hakbang.',
'Label_Offset_Y' => 'Patayong offset (mm)',
'Label_Offset_Y_Hint' => 'Inililipat ang print sa haba ng label. Taasan kapag naputol o nawawala ang itaas na bahagi ng disenyo; babaan kapag masyadong mababa ang simula nito.',
'Feed_To_Tear' => 'I-feed hanggang tear edge',
'Feed_To_Tear_Hint' => 'Isinusulong ang label sa tear bar pagkatapos ng bawat job. Iwanang naka-OFF kung bumababa ang print ng mga label o nahahati sa mga sticker — maraming printer ang hindi umaatras bago ang susunod na label.',
