'Ord_Guide_Payment_Paid' => 'Nakapagbayad na online ang customer sa pamamagitan ng payment gateway. Ang pagkumpirma sa order ay gumagawa ng benta bilang Bayad at nagtatala ng bayad para sa iyo — wala nang ibang gagawin.',
'Ord_Guide_Payment_Pending' => 'Cash on delivery, bank transfer o ibang pay-later na paraan. Ang pagkumpirma sa order ay gumagawa ng benta bilang Hindi Bayad, kaya ikaw mismo ang magtatala ng pera kapag nakolekta mo na ito — tingnan ang mga hakbang sa ibaba.',
