'Ord_Guide_MarkPaid_Step2' => 'Buksan ang Sales > All Sales at hanapin ang bentang iyon (parehong customer, at ipinapakita ng details page ang online order na pinagmulan nito).',
'Ord_Guide_MarkPaid_Step3' => 'Buksan ang menu ng mga aksyon ng row at piliin ang Gumawa ng Bayad.',
'Ord_Guide_MarkPaid_Step4' => 'Ilagay ang halaga, ang paraan ng pagbabayad at ang petsa, pagkatapos ay i-save. Kusang lilipat ang benta sa Bahagya o Bayad, depende sa halaga.',
'Ord_Guide_MarkPaid_Note' => 'Patuloy na itinatala ng Status ng Bayad na ipinapakita dito ang pinili sa checkout at nananatili ito. Ang benta ang accounting record, at ito ang nagpapakain sa iyong mga ulat ng bayad at kita. Gamitin ang Ipakita ang mga Bayad sa benta para suriin o i-edit ang inilagay mo.',
'Ord_Guide_Notes_Title' => 'Mabuting malaman',
'Ord_Guide_Note_Warehouse' => 'Ang warehouse na pinili mo sa pagkumpirma ang nagpapasya kung saan kukunin ang stock. Mamarkahang Out of Stock sa listahang iyon ang mga warehouse na hindi kayang sakupin ang buong order.',
'Ord_Guide_Note_Preorder' => 'Nilalaktawan ng mga pre-order na item ang pagsusuri ng stock, kaya maaaring kumpirmahin ang order na naglalaman ng mga ito kahit wala pa ang dami.',
'Ord_Guide_Note_Flagged' => 'Ang tag na Na-flag ay nangangahulugang nag-trigger ang order ng fraud check sa checkout. I-hover ang tag para makita ang dahilan at suriin ang order bago ito kumpirmahin.',
'Ord_Guide_Note_Cancel' => 'Posible lang ang pagkansela habang nakabinbin pa ang order. Kapag nakumpirma na, baligtarin ito sa pamamagitan ng benta o customer return sa halip.',


