'VG_Intro' => 'Ibinebenta ang variable na produkto bilang ilang variant. Buuin ang mga ito mula sa mga opsyon (inirerekomenda) o bilang simpleng listahan ng mga pangalan. Bawat variant ay may sariling code, presyo, larawan at stock.',
