'Upd_Note_Code_Changes_Lost' => 'Tala 1: Kung gumawa ka ng anumang pagbabago sa code nang mano-mano, mawawala ang iyong mga pagbabago.',
'Upd_Manual_Steps_Intro' => 'Pakisundan ang mga hakbang na ito para i-update ang iyong application',
'Upd_Note_Permission_Only' => 'Tala 2: admin lang o user na may permission na "{perm}" ang makakapag-upgrade ng system',
'Upd_Manual_Step_Backup_Db' => 'Gumawa ng backup ng iyong database. Pumunta sa {backup}, i-click ang Generate Backup — makikita mo ito sa {path} — o i-export ang iyong database mula sa PhpMyAdmin at i-save sa iyong PC.',
'Upd_Manual_Step_Backup_Files' => 'Gumawa ng backup ng iyong mga file bago mag-update.',
'Upd_Manual_Step_Download' => 'I-download ang pinakabagong bersyon mula sa iyong CodeCanyon account at i-extract ito.',
'Upd_Manual_Step_Remove' => 'Alisin ang mga nakaraang file, {except}:',
'Upd_Except' => 'maliban sa',
'Upd_File_Label' => 'file: {name}',
'Upd_Folder_Label' => 'folder: {name}',
'Upd_Manual_Step_Reupload' => 'I-upload muli ang mga file at folder mula sa bagong update, {except} ang parehong tatlong path sa itaas.',
'Upd_Manual_Step_Visit' => 'Bisitahin ang {url} para i-update ang iyong database.',
'Upd_Manual_Step_Clear_Cache' => 'I-hard-clear ang cache ng iyong browser.',
'Upd_Manual_Step_Done' => 'Tapos ka na! I-enjoy ang na-update na application.',
'Upd_Note_Blank_Pages' => 'Tala: Kung may mga page na hindi naglo-load o blangko, siguraduhing na-clear mo ang cache ng iyong browser.',
'Upd_Guide_Before_Title' => '1. Bago ka mag-update',
'Upd_Guide_Before_Download' => 'I-download ang {package} ng application mula sa iyong CodeCanyon account ({path}). Huwag itong i-extract — kailangan ng updater ang ZIP nang eksakto kung paano ito na-download.',
'Upd_Latest_Full_Zip' => 'pinakabagong buong ZIP package',
'Upd_Guide_Before_Admin' => 'Siguraduhing naka-log in ka bilang administrator na may {perm} na permission. Walang ibang makakakita o makakapagpatakbo ng updater.',
'Upd_Guide_Before_Quiet' => 'Pumili ng tahimik na sandali: habang nag-a-update, saglit na lilipat ang application sa maintenance mode at mala-lock out ang ibang user.',
'Upd_Guide_Before_No_Manual' => '{not} mo kailangang mag-backup nang mano-mano, mag-extract ng mga file, magpatakbo ng mga command, mag-edit ng configuration file, o galawin ang database — awtomatikong ginagawa iyon lahat ng updater. (Siyempre, hindi masama ang dagdag na manual backup.)',
'Upd_Not' => 'Hindi',
'Upd_Guide_Code_Overwritten' => 'Kung binago mo nang mano-mano ang code ng application, mapapatungan ng update ang iyong mga pagbabago. Laging napapanatili ang iyong data, upload, setting at .env.',
'Upd_Guide_Running_Title' => '2. Pagpapatakbo ng update',
'Upd_Guide_Run_Open' => 'Buksan ang {path} (ang page na ito) at manatili sa {tab} tab.',
'Upd_Guide_Run_Upload' => '{upload}: i-click o i-drag ang na-download na package sa upload box. Ina-upload ang malalaking file nang paunti-unti, kaya gumagana rin ito sa shared hosting na may mababang upload limit. Pinoprotektahan ng checksum laban sa sira o hindi kumpletong upload.',
'Upd_Upload_The_Zip' => 'I-upload ang ZIP',
'Upd_Guide_Run_Validation' => '{auto} pagkatapos ng upload (maaari mo itong patakbuhin muli gamit ang {button} button). Sinusuri ng system: integridad ng ZIP, istruktura at pagkakumpleto ng package, compatibility ng bersyon (tinatanggihan ang downgrade), kinakailangang bersyon at extension ng PHP, file permission, libreng disk space, koneksyon sa database, configuration, at na walang ibang update na tumatakbo.',
'Upd_Validation_Runs_Automatically' => 'Awtomatikong tumatakbo ang validation',
'Upd_Guide_Run_Review' => 'Suriin ang {panel} panel. Lumalabas lang ang {button} button kapag pumasa ang bawat kritikal na check. Kung may nabigong check, sasabihin ng mensahe kung ano mismo ang aayusin.',
'Upd_Guide_Run_Click' => 'I-click ang {button} at kumpirmahin. Pagkatapos ay {keep} at panoorin ang progress rail. Ginagawa ng system, ayon sa pagkakasunod:',
'Upd_Keep_Page_Open' => 'panatilihing bukas ang page na ito',
'Upd_Guide_Phase_Backup' => '{label} — gumagawa ng buong database dump, ZIP ng bawat application file na maaaring baguhin ng update, at kopya ng {env}, at {verified} ang mga ito. Hindi kailanman ginagalaw ng update ang iyong mga upload ({images}) at {storage}, kaya hindi ito ina-archive. Kung hindi makagawa ng backup, titigil dito ang update at walang mababago.',
'Upd_Verified' => 'vine-verify',
'Upd_Guide_Phase_Prepare' => '{label} — ine-extract ang bagong bersyon sa isang staging area at vina-validate muli. Hindi pa rin nagagalaw ang live na application.',
'Upd_Guide_Phase_Maintenance' => '{label} — ine-enable ang maintenance mode; nakakakita ang mga bisita ng magiliw na screen na "Babalik kami agad".',
'Upd_Guide_Phase_Files' => '{label} — halos agad na pinapalitan ang mga bagong file; itinatabi ang mga lumang file para sa rollback. Hindi kailanman pinapalitan ang mga protektadong path ({env}, {storage}, {images}).',
'Upd_Guide_Phase_Database' => '{label} — tumatakbo ang mga migration, pagkatapos ay nire-refresh ang mga permission, salin at template.',
'Upd_Guide_Phase_Cache' => '{label} — nili-clear at binubuo muli ang lahat ng cache.',
'Upd_Guide_Phase_Verify' => '{label} — kinukumpirma ng mga health check na nagbu-boot ang bagong bersyon, gumagana ang database, tumakbo ang lahat ng migration, at wasto ang configuration.',
'Upd_Guide_Phase_Done' => '{label} — inaalis ang maintenance mode at nililinis ang mga pansamantalang file.',
'Upd_Guide_Run_Success' => 'Kapag nakita mo ang {success}, i-click ang {reload} at i-hard-refresh ang iyong browser ({keys}) para ma-load ang mga bagong asset ng admin panel.',
'Upd_Update_Successful_Short' => 'Matagumpay ang update',
'Upd_Guide_No_Internet' => 'Hindi kailangan ng internet connection habang nag-a-update — lahat ay nagmumula sa na-upload na ZIP. Ang pagkawala ng koneksyon o pagsara ng browser ay HINDI sumisira sa update: natatandaan ng server kung saan mismo ito huminto.',
'Upd_Guide_Wrong_Title' => '3. Kung may magkaproblema',
'Upd_Guide_Wrong_Rollback' => '{label} — kung may mabigo pagkatapos magsimulang magbago ang mga file (error sa extraction, pagkabigo ng migration, nabigong health check, puno ang disk, …), awtomatikong ibinabalik ng system ang mga nakaraang file at ang database mula sa na-verify na backup, inaalis ang maintenance mode, at iniuulat ang {message}. Babalik ka sa eksaktong pinagsimulan mo.',
'Upd_Automatic_Rollback' => 'Awtomatikong rollback',
'Upd_Failed_Previous_Restored' => 'Nabigo ang update — naibalik ang nakaraang bersyon',
'Upd_Guide_Wrong_Interrupted' => '{label} (pag-restart ng server, timeout, pagsara ng browser, pagkawala ng kuryente) — kapag binuksan mo muli ang page na ito, nag-aalok ang pulang banner ng dalawang ligtas na pagpipilian: {resume} (nagpapatuloy mula sa eksaktong hakbang kung saan ito huminto) o {rollback} (ibinabalik ang nakaraang bersyon mula sa backup).',
'Upd_Interrupted_Update' => 'Naantalang update',
'Upd_Guide_Wrong_Unreachable' => '{label} — gamitin ang standalone na {console} sa {path}. Gumagana ito kahit nasa maintenance mode ang site o sira ang mga asset ng admin panel, at nag-aalok ng parehong Continue / Roll back na aksyon. Mayroon ding hindi gaanong kapansin-pansing link na "Administrator access" sa ibaba ng maintenance screen.',
'Upd_Admin_Unreachable' => 'Hindi maabot ang admin panel',
'Upd_Recovery_Console' => 'recovery console',
'Upd_Guide_Wrong_Locked_Out' => '{label} — habang tumatakbo ang update, nagpapakita ang page na ito ng {link}. I-save ito kung kailangan mong makabalik (halimbawa pagkatapos mag-expire ng iyong session); pinapalusot ka nito sa maintenance screen para makapag-log in ka muli.',
'Upd_Locked_Out_Maintenance' => 'Na-lock out dahil sa maintenance mode',
'Upd_Bypass_Link' => 'bypass link',
'Upd_Guide_Wrong_Concurrent' => '{label} — makikita nila ang {message} Isang update lang ang maaaring tumakbo sa bawat pagkakataon.',
'Upd_Another_Admin_Updating' => 'May ibang admin na sumusubok mag-update nang sabay',
'Upd_Guide_Backups_Title' => '4. Mga backup at restore',
'Upd_Guide_Backups_Created' => 'Bawat update ay gumagawa ng backup {before} gumalaw ng anuman: lahat ng application file na maaaring palitan ng update, kopya ng {env}, at buong database dump. Hindi kailanman binabago ng update ang mga upload at {storage} kaya hindi sila kasama — magtago ng sarili mong backup ng mga iyon. Nasa {path} ang mga backup at hindi kailanman naa-access mula sa web.',
'Upd_Before' => 'bago',
'Upd_Guide_Backups_Panel' => 'Inililista ng {panel} panel sa {tab} tab ang mga ito kasama ang petsa, bersyon at laki. Mula doon maaari mong {restore} ang anumang kumpletong backup (mga file + database — kinukuha muna ang safety copy ng kasalukuyang database) o {delete} ang mga luma.',
'Upd_Restore_Verb' => 'i-restore',
'Upd_Delete_Verb' => 'i-delete',
'Upd_Guide_Backups_Retention' => 'Gamitin ang {keep} para piliin kung ilang backup ang itatago; awtomatikong inaalis ang mga mas luma pagkatapos ng bawat matagumpay na update. Hindi kailanman mabubura ang tanging natitirang kumpletong backup — lagi kang may daan pabalik.',
'Upd_Guide_Manual_Title' => '5. Manual na update (fallback na paraan)',
'Upd_Guide_Manual_Text' => 'Kung mas gusto mong mag-update nang mano-mano, o hindi magamit ang uploader sa iyong server, sundan ang sunud-sunod na tagubilin sa {tab} tab ng page na ito.',
'Upd_Guide_Clear_Cache_First' => 'Kung mukhang sira o blangko ang mga page pagkatapos ng anumang update, i-clear muna ang cache ng iyong browser — halos palagi itong ang sanhi.',
'Upd_Restore_Backup_Confirm' => 'I-restore ang backup na ito? Papalitan ng backup ang kasalukuyang mga file at kasalukuyang database. Kinukuha muna ang safety copy ng kasalukuyang database. (v{version} — {date})',
'Woo_Guide_Lead' => 'Paano nananatiling tugma ang WooCommerce shop sa ERP. Ang mga cron line sa ibaba ay binuo para sa server na ito, kaya maaaring kopyahin nang direkta dito.',
'Woo_Guide_Ways_Note' => 'Hindi tulad ng Shopify, walang ipinapadala ang WooCommerce sa ERP nang kusa — walang webhook receiver dito, kaya lahat ng papasok ({in}) ay dumarating ayon sa iskedyul. Ang stock lang na palabas ({out}) ang maaaring agaran.',
'Woo_In' => 'papasok',
'Woo_Out' => 'palabas',
'Woo_Guide_Both_Ways_Title' => 'Kailangan muna ito para sa parehong direksyon',
'Woo_Api_Keys' => 'Mga API key',
'Woo_Guide_Api_Keys_Text' => '{path}, permission {perm}. Kopyahin ang consumer key at secret sa {settings} tab, kasama ang store URL — ang address ng iyong site na walang trailing slash, hal. {example}.',
'Woo_Credentials_Saved' => 'na-save ang mga credential',
'Woo_Not_Configured_Yet' => 'hindi pa naka-configure',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress application password (opsyonal)',
'Woo_Guide_Wp_App_Password_Text' => 'Ginagamit lang para sa mga larawan ng produkto. Inililipat ng WooCommerce API ang mga produkto, stock, kategorya, brand, customer at order; ang WordPress API ang naghahanap sa Media Library at nag-a-upload ng larawang wala pa doon.',
'Woo_Guide_Wp_App_Password_Note' => 'Gumamit ng WordPress user na kayang mamahala ng media, at gawin ang password sa ilalim ng {path}. Iwanang blangko ang parehong field at magsi-sync pa rin ang lahat — ang pag-attach lang ng larawan ang nilalaktawan.',
'Woo_Guide_Pick_Way_Title' => 'Pagkatapos ay piliin kung paano ito mananatiling tugma',
'Woo_Right_Away' => 'Agad-agad',
'Woo_Stock_Live' => 'live ang stock',
'Woo_Stock_Not_Live' => 'hindi live ang stock',
'Woo_Guide_Realtime_Lead' => 'Isang direksyon lang: stock at mga produktong palabas ng ERP. Ang mga order at pag-edit ng produkto na ginawa sa WooCommerce ay dumarating pa rin ayon sa iskedyul — tingnan ang kabilang tab.',
'Woo_Push_Stock_On_Change' => 'I-push ang stock sa sandaling magbago ito',
'Woo_Setting_People_Miss' => 'Ito ang setting na madalas makaligtaan',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Ang POS sale ay {not} umaabot sa WooCommerce nang kusa. Kapag naka-off, malalaman lang ng shop sa susunod na stock sync — isang oras, bilang default — at sa panahong iyon maaari itong magbenta ng unit na naibenta mo na sa till.',
'Woo_Does_Not' => 'hindi',
'Woo_Guide_Tick_Instant' => 'I-tick ang {option} sa {settings} tab. Iyon na ang buong setup — walang worker, walang cron. Bawat benta, return, adjustment, transfer at natanggap na pagbili ay magpapadala ng push ng mga produktong iyon lang, pagkatapos ma-save ang benta, at ang benta na may dalawampung linya ay isang push lang, hindi dalawampu. Hindi kailanman naghihintay ang till dito.',
'Woo_Currently' => 'Kasalukuyan:',
'Woo_Instant_On_Text' => 'on — pinu-push ang stock kapag nagbago',
'Woo_Instant_Off_Text' => 'off — ayon sa iskedyul lang ang stock',
'Woo_Guide_Instant_Note' => 'Ang mga produktong naka-link na sa WooCommerce lang ang pinu-push — ang hindi pa kailanman na-sync ay walang maitatama sa shop. Dumadaan sa parent ang mga variable product, at muling pinu-push ang combo kapag gumalaw ang alinman sa mga component nito. Ang mga bulk operation (pag-delete ng produkto, pag-reset ng warehouse) ay sumusulat ng stock nang hindi nagpapalabas ng event, na isang dahilan para panatilihin din ang oras-oras na stock sync.',
'Woo_Push_Products_On_Save' => 'I-push ang mga produkto sa sandaling ma-save',
'Woo_Guide_Tick_Auto_Products' => 'I-tick ang {option} sa {settings} tab at ang produktong ginawa, in-edit o dinuplicate sa Stocky ay ipapadala sa WooCommerce pagkatapos itong ma-save — mga detalye, presyo, variant at larawan, pagkatapos ay ang stock nito. Agad na gagawin ang bagong produkto sa shop sa halip na maghintay sa gabi-gabing products sync.',
'Woo_On' => 'naka-on',
'Woo_Off' => 'naka-off',
'Woo_Guide_Bulk_Imports_Note' => 'Hindi pinu-push isa-isa ang mga bulk import — magpatakbo ng products sync pagkatapos ng import. I-sync muna ang mga kategorya at brand, para mapunta sa tamang kategorya ang pinu-push na produkto.',
'Woo_Nothing_Else_To_Install' => 'Wala nang ibang i-install',
'Woo_Guide_Same_Process' => 'Walang queue worker, walang cron entry. Tumatakbo ang push sa parehong proseso na nagsilbi sa benta, {after} maibalik ang response, kaya hindi kailanman naghihintay ang till sa WooCommerce. Hindi kailanman nagsasapawan ang mga push: ang mga pagbabagong ginawa habang may tumatakbo ay maghihintay dito at lalabas pagkatapos.',
'Woo_After' => 'pagkatapos',
'Woo_Guide_Shop_Stops_Answering' => 'Ang shop na tumigil sumagot ay sinusukuan pagkalipas ng walong segundo, at humihinto ang mga push nang limang minuto para hindi na muling maghintay dito ang bawat benta; ang mga pagbabagong dumating habang naghihintay ay lalabas kasama ng unang push pagkatapos ng pause, at hahabol pa rin ang oras-oras na stock sync. Naitatala ang bawat pause sa Logs tab.',
'Woo_Guide_Artisan_Exception' => 'Isang eksepsiyon: ang pagbabago ng stock na ginawa ng artisan command ay walang response na susundan, kaya ipinipila ito sa {queue} sa halip. Para mailabas din agad ang mga iyon, patakbuhin ang queue na iyon:',
'Woo_Cron_Line_Copied' => 'Nakopya ang cron line',
'Woo_Command_Copied' => 'Nakopya ang command',
'Woo_Guide_Not_Woo_Queue' => 'Sadyang hindi ang {queue} queue: dala niyon ang mga oras-oras na catalogue batch, at ang instant push na nakapila sa likod ng isa ay hindi na magiging instant.',
'Woo_On_A_Schedule' => 'Ayon sa iskedyul',
'Woo_Guide_Scheduled_Lead' => 'Muling sinusuri ang lahat paminsan-minsan, sa parehong direksyon. Ganito umaabot ang mga order sa ERP, kung paano nai-publish ang catalogue, at kung ano ang nag-aayos sa anumang nakaligtaan ng mabilis na daan. Bawat job ay may sariling cron entry, kaya ang gusto mo lang ang patatakbuhin mo.',
'Woo_Guide_Sync_Drains_Queue' => 'Pinapatakbo ng {command} ang sarili nitong queue habang tumatakbo ito, kaya hindi kailangan ng hiwalay na worker ang mga linyang ito. Sa Windows, gamitin ang Task Scheduler na may program na {program} at parehong mga argument, sinimulan sa {path}.',
'Woo_Or_No_Cron' => 'O walang cron',
'Woo_Guide_No_Cron_Text' => 'Bawat tab dito ay nagsi-sync kapag hiniling, at pinapatakbo ng manual sync ang sarili nitong mga batch habang bukas ang page — kaya ang maliit na shop ay maaaring tumakbo nang walang anumang cron entry. Ang mawawala ay lahat ng nangyayari habang walang nakatingin: dumarating lang ang mga order kapag may pumindot ng button.',
'Woo_Commands_Worth_Knowing' => 'Mga command na dapat malaman',
'Woo_Worth_Knowing' => 'Dapat malaman',
'Woo_Guide_Changing_Url_Clears' => 'Ang pagpapalit ng store URL o ng mga API key ay nagki-clear ng bawat mapping — muling magsi-sync ang mga produkto, kategorya, brand at customer sa bagong store.',
'Woo_Guide_Keep_Skus' => 'Panatilihing pare-pareho ang mga SKU sa pagitan ng Stocky at WooCommerce: iyon ang pumipigil sa mga duplicate at nagpapaligtas sa muling pag-link.',
'Woo_Guide_Stock_Total' => 'Ang stock na nai-publish sa Woo ay ang {total}, hindi ang bilang ng iisang warehouse.',
'Woo_Total_Across_Warehouses' => 'kabuuan sa bawat warehouse',
'Woo_Guide_Full_Reference' => 'Ang buong reference — bawat scope, paano gumagana ang queue, at listahan ng troubleshooting — ay nasa {file}.',
'Woo_Way_Covers' => 'Sakop',
'Woo_Way_Covers_Realtime' => 'Stock na palabas ng ERP lang — POS sale, return, adjustment, natanggap na pagbili',
'Woo_Way_Covers_Scheduled' => 'Lahat, sa parehong direksyon: papasok ang mga order at pagbabago ng produkto, palabas ang catalogue at stock',
'Woo_Way_Speed' => 'Bilis',
