'Woo_Way_Cron_Entries_Below' => 'Ang mga cron entry sa ibaba',
'Woo_Cron_Orders' => 'Mga order bawat 15 minuto — ang mga nagbago lang mula sa huling run.',
'Woo_Cron_Products_Pull' => 'Mga pagbabago ng produkto mula sa shop, gabi-gabi sa 03:00.',
'Woo_Cron_Customers' => 'Mga customer, gabi-gabi sa 03:30.',
'Woo_Cron_Stock' => 'Stock bawat oras — ang safety net sa ilalim ng instant push, at ang tanging stock sync kung wala ito.',
'Woo_Cron_Products_Push' => 'Mga produktong hindi pa naka-link, gabi-gabi sa 02:00. Hindi muling isinusulat ang mga kasalukuyang produkto.',
'Woo_Cmd_Stock' => 'I-push ngayon ang stock para sa bawat naka-link na produkto.',
