'Woo_Cmd_Pull' => 'Lahat ng papasok nang sabay: mga produkto, order, customer.',
'Woo_Guide_Page_Title' => 'Gabay sa WooCommerce',
'Woo_Guide_Page_Subtitle' => 'Pagkonekta sa shop, kung ano ang tumatakbo nang kusa, at ang mga cron entry para sa server na ito',
'Woo_Settings_Button' => 'Mga setting ng WooCommerce',
'Woo_No_Shop_Connected' => 'Wala pang nakakonektang shop',
'Woo_No_Shop_Connected_Desc' => 'Nalalapat pa rin ang lahat sa ibaba — ilagay ang store URL at mga API key sa WooCommerce settings page, pagkatapos ay bumalik.',
'Woo_Wp_Username' => 'WordPress username',
'Woo_Wp_App_Password' => 'WordPress application password',
'Woo_Settings_Instant_Hint' => 'Ang benta, return o adjustment ay nagpapadala ng stock push para sa mga produktong iyon lang sa sandaling ma-save, kaya tama ang shop sa loob ng ilang segundo sa halip na sa susunod na oras-oras na stock sync. Wala nang ibang i-install — tumatakbo ang push pagkatapos masagot ang benta, kaya hindi kailanman naghihintay ang till sa WooCommerce. Higit pa sa {guide} tab.',
'Woo_Settings_Instant_Off_Alert' => 'Kapag naka-off, umaabot lang sa WooCommerce ang POS sale sa susunod na stock sync — hanggang isang oras pagkatapos.',
'Woo_Settings_Auto_Products_Hint' => 'Ang produktong ginawa, in-edit o dinuplicate sa Stocky ay ipinapadala sa WooCommerce pagkatapos itong ma-save — mga detalye, presyo, variant, larawan, pagkatapos ay ang stock nito — sa halip na maghintay sa products sync. Hindi pinu-push ang mga bulk import; magpatakbo ng products sync pagkatapos ng import.',
'Woo_Sync_Tuning' => 'Pag-tune ng sync',
'Woo_Sync_Tuning_Intro' => 'Angkop ang mga default sa karamihan ng store. Baguhin lang ang mga ito kung mabagal o nagta-time out ang sync sa iyong hosting. Bawat value ay nililimitahan sa ligtas na range, at ang pag-clear sa field ay ibinabalik ang default nito.',
'Woo_Setting_This_Up' => 'Pag-set up nito',
'Woo_Setting_This_Up_Text' => 'Ang pagkuha ng mga API key, para saan ang WordPress application password, ang mga cron entry para sa naka-iskedyul na sync, at kung paano maaabot ng stock ang shop sa sandaling magbago ito — lahat ng iyon, kasama ang sariling cron line ng server na ito na handang kopyahin, ay nasa Guide tab. Iisang kopya, kaya hindi ito maaaring lumihis sa aktwal na ginagawa ng module.',
