'Slack_Notifications' => 'Mga Slack notification',
'Slack_Hero_Desc' => 'I-post ang mga benta, pagbili, bayad at stock alert sa isang Slack channel habang nangyayari ang mga ito.',
'Slack_Incoming_Webhook_URL' => 'Incoming webhook URL',
