'Telegram_Hero_Desc' => 'Ipadala ang mga benta, pagbili, bayad at gastos sa isang Telegram chat o grupo sa pamamagitan ng iyong bot.',
'Telegram_Bot_Token' => 'Bot token',
'Telegram_Bot_Token_Help' => 'Gumawa ng bot gamit ang {bot} sa Telegram at i-paste ang token nito dito.',
'Telegram_Chat_ID' => 'Chat ID',
'Telegram_Chat_ID_Placeholder' => 'hal. {example} para sa grupo, o user id',
'Telegram_Chat_ID_Help' => 'Idagdag ang bot sa iyong grupo o channel, pagkatapos ay kunin ang chat id — halimbawa sa pag-forward ng mensahe sa {bot}, o mula sa {api} API response ng bot.',
'Telegram_Pick_Events' => 'Piliin ang mga event na ipapadala',
'Telegram_Enable_Notifications' => 'I-enable ang mga Telegram notification',
'Telegram_Test_Sent' => 'Naipadala ang test message — tingnan ang iyong Telegram chat.',
'Telegram_G_Lead' => 'Paano makukuha ang mga notification ng Stocky sa isang Telegram chat, grupo o channel.',
'Telegram_G_Lead_Cron' => 'Ang cron line sa ibaba ay binuo para sa server na ito, kaya maaari itong kopyahin nang direkta dito.',
'Telegram_G_Set_It_Up' => 'I-set up ito',
'Telegram_G_Step1_Title' => 'Gawin ang bot',
'Telegram_G_Step1_Body' => 'Sa Telegram, magbukas ng chat kay {botfather}, ipadala ang {cmd}, at pumili ng pangalan at username para sa bot. Sasagot ang BotFather ng {token} tulad ng {example} — kopyahin ito.',
'Telegram_G_Bot_Token_Inline' => 'bot token',
'Telegram_G_Step2_Title' => 'Hanapin ang chat ID',
'Telegram_G_Step2_Intro' => 'Kung saan pupunta ang mga mensahe ang magpapasya kung aling ID ang kailangan mo:',
'Telegram_G_Own_Chat' => '{label} — magpadala muna ng anumang mensahe sa iyong bagong bot (hindi makapagsisimula ng usapan ang bot), pagkatapos ay padalhan ng mensahe si {bot}: sasagot ito ng iyong user ID.',
'Telegram_G_Your_Own_Chat' => 'Ang sarili mong chat',
'Telegram_G_Group' => '{label} — idagdag ang bot sa grupo at mag-post ng mensahe doon.',
'Telegram_G_A_Group' => 'Isang grupo',
'Telegram_G_Channel' => '{label} — idagdag ang bot bilang {admin} ng channel at mag-post ng mensahe doon.',
'Telegram_G_A_Channel' => 'Isang channel',
'Telegram_G_Administrator' => 'administrator',
'Telegram_G_GetUpdates_Intro' => 'Para sa grupo o channel, buksan ang address na ito sa browser na may sarili mong token, at i-refresh ito pagkatapos mag-post:',
'Telegram_G_Chat_Id_Note' => 'Hanapin ang {json}. Negatibo ang ID ng grupo o channel, hal. {example} — kopyahin lahat, kasama ang minus sign.',
'Telegram_G_Step3_Title' => 'Ikonekta ito dito',
'Telegram_G_Step3_Body' => 'Sa {settings} tab i-paste ang bot token at chat ID, piliin ang {all} o ang mga event lang na gusto mo {events}, i-on ang {enable} at i-save. Pagkatapos ay pindutin ang {test}.',
'Telegram_G_State_Enabled' => 'naka-enable',
'Telegram_G_State_Off' => 'naka-save, pero naka-off',
'Telegram_G_State_Not_Configured' => 'hindi pa naka-configure',
'Telegram_G_Chat_Label' => 'chat {id}',
'Telegram_G_How_Sent' => 'Paano ipinapadala ang mga mensahe',
'Telegram_G_A_Title' => 'Agad-agad — walang i-install',
'Telegram_G_A_Body' => 'Ang benta, pagbili, bayad o gastos na na-save sa Stocky — sa POS o sa admin — ay ipinapadala sa Telegram {after} itong ma-save, sa parehong request. Walang cron entry, walang queue worker, at hindi kailanman naghihintay ang cashier sa Telegram: nasagot na ang benta kapag lumabas ang mensahe.',
'Telegram_G_Right_After' => 'pagkatapos mismo',
'Telegram_G_B_Title' => 'Ang cron entry — para sa mga retry at background event',
'Telegram_G_B_Body' => 'Dalawang uri ng mensahe ang naghihintay sa sariling queue ng Telegram sa halip: ang pagpapadalang nabigo (saglit na hindi maabot ang Telegram), na inuulit hanggang tatlo pang beses sa susunod na ilang minuto; at mga event na nangyari sa labas ng admin — mga order na na-import mula sa WooCommerce o Shopify, mga artisan command. Ang cron entry na ito ang nagpapadala sa mga iyon, at wala nang iba:',
'Telegram_G_Cron_Note' => 'Tama ang bawat minuto: ang run na walang naghihintay ay agad na lumalabas. Sa cPanel, ilagay ito sa {cronJobs} — gamitin ang buong path sa PHP 8.2+ kung mas luma ang {php}. Sa Windows, gamitin ang Task Scheduler na may program na {program}, mga argument na {args}, sinimulan sa {path}.',
'Telegram_G_Waiting' => '{n} naghihintay na maipadala',
