'Xero_Redirect_Uri_Title' => 'Redirect URI para sa Xero app',
'Xero_Redirect_Uri_Help' => 'Gumawa ng "Web app" sa {link} at i-register ang redirect URI na ito. Tandaan: awtomatikong nire-refresh ang mga Xero access token, pero ang koneksyong idle nang higit sa 60 araw ay kailangang ikonekta muli.',
'Xero_Total_Customers' => 'Kabuuang customer',
'Xero_Contacts_In_Xero' => 'Mga contact sa Xero',
