'Xero_Push_Customers_To' => 'I-push ang mga customer sa {name}',
'Xero_Push_Customers_Desc' => 'Gumagawa o nag-a-update ng Xero contact para sa bawat customer. Ang customer na may pangalang mayroon na sa Xero ay ili-link sa contact na iyon.',
'Xero_Push_Customers' => 'I-push ang mga customer',
'Xero_Push_Sales_Invoices' => 'I-push ang mga benta bilang invoice',
'Xero_Push_Invoices_Desc' => 'Gumagawa ng isang AUTHORISED na invoice kada benta (invoice number = Ref ng benta), kasama ang mga line item ng benta at mga linya ng shipping, discount at tax para tumugma ang kabuuan sa Xero sa kabuuan ng benta. Nilalaktawan ang mga bentang nasa Xero na — hindi kailanman ine-edit ang mga invoice. Ginagawa agad ang mga nawawalang contact.',
'Xero_Push_Invoices' => 'I-push ang mga invoice',
'Xero_Reset_Contact_Confirm' => 'I-reset ang mga link ng contact? Ili-link muli o gagawin muli ang mga ito sa susunod na push.',
'Xero_Reset_Contact_Links' => 'I-reset ang mga link ng contact',
'Xero_Guide_1' => 'Gumawa ng {webApp} sa {link} ({menu}).',
'Xero_Guide_2' => 'I-register ang redirect URI na ipinapakita sa Connection tab.',
'Xero_Guide_3' => 'Kopyahin ang {clientId} ng app at gumawa ng {clientSecret}; i-paste ang dalawa dito at i-save.',
'Xero_Guide_4' => 'I-click ang {connect}, mag-sign in at piliin ang organisation na ikokonekta.',
'Xero_Guide_5' => 'Suriin ang mga account code: tumatanggap ng mga linya ng invoice ang sales account; magtakda ng bank account code kung dapat ding magtala ng bayad ang mga bayad na benta.',
'Xero_Guide_6' => 'I-push muna ang mga customer, pagkatapos ay ang mga invoice. Ang mga invoice number ay ang mga Ref ng benta, kaya tinatanggihan ng Xero ang mga duplicate kahit i-reset ang mga link.',
'Xero_Amounts_Title' => 'Ipinu-push ang mga halaga nang tax-inclusive kung ano ito',
'Xero_Amounts_Desc' => 'Gumagamit ang mga invoice ng mga NoTax na linya na eksaktong kahawig ng benta (items + shipping − discount + tax), kaya laging katumbas ng kabuuan sa Xero ang kabuuan sa Stocky. Maaaring i-remap ng iyong accountant ang mga linya ng tax at shipping sa tamang account sa loob ng Xero.',
'Xero_Org_Connected' => 'Nakakonekta ang Xero organisation.',
'Jumia_Hero_Title' => 'Pag-sync ng marketplace sa Jumia',
'Jumia_Hero_Desc' => 'I-push ang mga presyo at stock sa iyong mga Jumia Seller Center listing at i-import ang mga marketplace order bilang benta.',
'Jumia_Api_Url_Label' => 'API URL (Seller Center endpoint ng iyong bansa)',
'Jumia_Account_Email' => 'Email ng account (User ID)',
'Jumia_Api_Key' => 'API key',
'Jumia_Prices_Stock' => 'Mga Presyo at Stock',
'Jumia_Push_Prices_Stock_Title' => 'I-push ang mga presyo at stock sa Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'Ipinapadala ang kasalukuyang presyo at dami para sa bawat produkto (at variant) na may SKU na tumutugma sa {sku} ng Jumia listing. Isinusumite ang mga update bilang Seller Center feed at inilalapat nang asynchronous — naitatala ang feed ID sa Logs tab, at lumalabas ang mga pagtanggi kada item sa feed status screen ng Seller Center.',
'Jumia_Push_Prices_Stock' => 'I-push ang mga presyo at stock',
'Jumia_Pull_Orders_Desc' => 'Ini-import ang mga marketplace order bilang benta (mga reference tulad ng {ref}), itinutugma sa iyong mga produkto ayon sa Seller SKU. Nilalaktawan ang mga na-import na at kinanselang order, kaya ligtas ang regular na pag-pull. Minamarkahang bayad ang mga bayad para lang sa mga naihatid na order (karamihan ay COD sa Jumia).',
'Jumia_Guide_1' => 'Sa Jumia {sellerCenter}, buksan ang {menu} at gumawa ng API key.',
'Jumia_Guide_2' => 'Ilagay ang API URL ng iyong bansa (hal. {ng} para sa Nigeria, {ke} para sa Kenya, {eg} para sa Egypt), ang email ng iyong Seller Center account, at ang key — pagkatapos ay patakbuhin ang {test}.',
'Jumia_Guide_3' => 'Siguraduhing ang {sku} ng bawat Jumia listing ay katumbas ng Stocky product code — iyon ang pagkakakilanlang ginagamit para sa parehong stock push at pagtutugma ng order.',
'Jumia_Guide_4' => 'I-push ang mga presyo at stock pagkatapos ng mga pagbabago sa imbentaryo; regular na i-pull ang mga order (walang webhook ang Jumia sa API na ito).',
'Jumia_Guide_5' => 'Ang paggawa ng mga bagong listing ay nananatili sa Seller Center — nangangailangan ang Jumia ng mga attribute na partikular sa kategorya at pagsusuri ng larawan na ang kanilang portal lang ang mahusay na humahawak.',
'Mailchimp_Hero_Title' => 'Pag-sync ng audience sa Mailchimp',
'Mailchimp_Hero_Desc' => 'Panatilihing puno ng iyong mga customer ang Mailchimp audience, para makapagpatakbo ka ng mga email campaign sa iyong totoong customer base.',
'Mailchimp_Account_Audience' => 'Account at audience',
'Mailchimp_Api_Key_Ph' => 'hal. {example} ({menu})',
'Mailchimp_Audience_Option' => '{name} ({n} miyembro)',
'Mailchimp_Load_Audiences_Ph' => 'I-load ang mga audience para pumili ng isa',
'Mailchimp_Load_Audiences' => 'I-load ang mga audience',
'Mailchimp_Double_Optin_Label' => 'Double opt-in — nakakatanggap ang mga bagong miyembro ng confirmation email bago sumali',
'Mailchimp_Double_Optin_Hint' => '(inirerekomenda para sa GDPR)',
'Mailchimp_Auto_Sync_Customers' => 'Awtomatikong i-sync ang mga bagong customer habang ginagawa ang mga ito',
'Mailchimp_With_Email' => 'May email',
'Mailchimp_Push_Desc' => 'Ina-upsert ang bawat customer na may email address sa napiling audience (kasama ang pangalan at telepono). Pinapanatili ng mga kasalukuyang miyembro ang kanilang subscription status — walang nag-unsubscribe na muling isu-subscribe. Hindi isinasama ang mga customer na walang email.',
'Mailchimp_Double_Optin_Off_Title' => 'Naka-off ang double opt-in',
'Mailchimp_Double_Optin_Off_Desc' => 'Idadagdag ang mga bagong miyembro bilang subscribed nang walang confirmation email. Gawin lang ito para sa mga customer na pumayag nang tumanggap ng marketing.',
'Mailchimp_Guide_1' => 'Sa Mailchimp, buksan ang {menu} at gumawa ng key (nagtatapos ito sa {suffix} — ang suffix na iyon ang iyong datacenter).',
'Mailchimp_Guide_2' => 'I-paste ang key dito, i-save, pagkatapos ay i-click ang {load} at piliin ang audience na pupunuin.',
'Mailchimp_Guide_3' => 'Iwanang naka-on ang {doubleOptIn} maliban kung pumayag na ang iyong mga customer sa mga marketing email.',
'Mailchimp_Double_Optin_Term' => 'double opt-in',
'Mailchimp_Guide_4' => 'Patakbuhin ang {push} para sa unang pagpuno; i-on ang {autoSync} para awtomatikong sumali ang mga bagong customer.',
'Mailchimp_Auto_Sync_Term' => 'auto-sync',
'Mailchimp_Consent_Title' => 'Mahalaga ang pahintulot',
'Mailchimp_Consent_Desc' => 'Ang pag-email sa mga taong hindi kailanman pumayag sa marketing ay maaaring lumabag sa GDPR/CAN-SPAM at maging sanhi ng pag-suspend ng iyong Mailchimp account. Inililipat ng double opt-in ang kumpirmasyon sa Mailchimp — ang ligtas na default.',
'Mailchimp_No_Audiences' => 'Walang nahanap na audience sa account na ito.',
