'Shopify_Client_Info' => 'Mula Enero 2026, hindi na gumagawa ang Shopify ng mga custom app sa admin. Gawin ang app sa {dashboard}, ibigay ang mga Admin API scope nito, i-install ito sa shop na ito, pagkatapos ay kopyahin ang Client ID at Client secret mula sa {settings} page nito. Kumukuha ang ERP ng bagong access token nang kusa bawat 24 oras. Dapat nasa parehong Shopify organisation ang app at ang shop.',
