'Shopify_Create_Missing_Products' => 'Gumawa ng mga ERP product para sa mga Shopify product na hindi tumutugma sa SKU',
'Shopify_Create_Missing_Customers' => 'Gumawa ng mga ERP customer para sa mga Shopify customer na hindi tumutugma sa email',
'Shopify_Unknown_Customer_Hint' => 'Kapag naka-off ito, nilalaktawan ang order mula sa hindi kilalang customer sa halip na hulaan.',
'Shopify_Entities_Lead' => 'Ang mga entity lang na naka-on dito ang maaaring i-sync — ang shop na kinukunan mo lang ng mga order ay hindi dapat magkaroon ng ligaw na product push na muling isinusulat ang catalogue nito.',
'Shopify_Auto_Schedule' => 'Awtomatikong mag-sync ayon sa iskedyul',
'Shopify_Auto_Schedule_Hint' => 'Nangangailangan ng cron entry sa server na nagpapatakbo ng {cmd} (bawat 5 minuto ang pinakamaliit na magagamit ng mga interval sa ibaba). Maaaring laging simulan nang mano-mano ang mga sync.',
'Shopify_Push_Stock_On_Change' => 'I-push ang stock sa sandaling magbago ito',
'Shopify_Push_Stock_Hint' => 'Ang benta, return o adjustment ay nagpapadala ng stock push para sa mga produktong iyon lang sa sandaling ma-save, kaya tama ang shop sa loob ng ilang segundo sa halip na sa susunod na naka-iskedyul na run. Wala nang ibang i-install — tumatakbo ang push pagkatapos masagot ang benta, kaya hindi kailanman naghihintay ang till sa Shopify.',
'Shopify_Switch_Inventory_First' => 'I-on muna ang Inventory sa ilalim ng {tab}.',
'Shopify_Leave_Off_Lag' => 'Kapag naka-off, umaabot lang sa Shopify ang POS sale sa susunod na Inventory push — hanggang {n} minuto pagkatapos.',
