'Shopify_Using_Default_Plan' => 'Ginagamit ang default na plano',
'Shopify_Default_Plan_Desc' => 'Ipinapasok ang mga order at inilalabas ang stock, bawat {n} minuto. Magdagdag ng hakbang para pumili ng sarili mo — ang pag-clear muli sa listahan ay ibinabalik ang default na ito.',
