'Shopify_Manual' => 'Manual',
'Shopify_Due_Now' => 'Due na ngayon',
'Shopify_Auto_Off_Note' => 'Naka-off — tumatakbo lang ang mga hakbang na ito kapag may pumindot ng Sync.',
'Shopify_Auto_On_Note' => 'Pinapatakbo ng cron entry na nagpapatakbo ng {cmd} — kung wala ito, walang tatakbo dito nang kusa. Ang manual sync ay binibilang bilang run: itinutulak nito ang susunod ayon sa interval ng hakbang.',
'Shopify_Stock_Lag_Title' => 'Umaabot lang ang stock sa Shopify kapag tumakbo ang Inventory push step',
'Shopify_Stock_Lag_Desc' => 'Hindi makikita ng shop ang benta sa counter hanggang noon — hanggang {n} minuto, kaya maaari pang maibenta online nang dalawang beses ang huling unit. I-on ang {setting} at ipapadala sa loob ng ilang segundo ang bawat benta, return at adjustment sa halip.',
'Shopify_Turn_It_On' => 'I-on ito',
'Shopify_Stock_Also_Pushed' => 'Pinu-push din ang stock sa loob ng ilang segundo ng anumang benta, return o adjustment, nang hindi naghihintay sa hakbang sa itaas.',
'Shopify_Sync_History' => 'Kasaysayan ng sync',
'Shopify_Nothing_Run_Store' => 'Wala pang tumakbo para sa store na ito',
'Shopify_Hook_Msg_Client' => 'I-click ang “Register webhooks” sa ibaba — walang kailangang ilagay sa Shopify.',
'Shopify_Hook_Msg_Token' => 'I-click ang “Register webhooks” sa ibaba, at i-paste ang API secret key ng app sa store settings bilang signing secret.',
'Shopify_Hook_Note_Register' => 'Ang pag-register ay gumagawa ng mga subscription sa Shopify at awtomatikong itinuturo ang mga ito sa address na ito. Huwag itong idagdag nang mano-mano sa ilalim ng Shopify → Settings → Notifications → Webhooks: pinipirmahan ang mga iyon ng ibang secret at tatanggihan ang bawat delivery.',
'Shopify_Hook_Verified_Client' => 'Vine-verify ang mga delivery gamit ang client secret ng app, na naka-store na.',
'Shopify_Hook_Signature_Required' => 'Tinatanggihan ang mga delivery na walang wastong signature, kaya kailangang nakatakda ang secret bago gumana ang mga webhook.',
'Shopify_Hook_Retries' => 'Inuulit ng Shopify hanggang makakuha ito ng 2xx, at isang beses lang naitatala ang bawat delivery — walang epekto ang inulit na event, hindi ito duplicate na order.',
'Shopify_No_Signing_Secret' => 'Walang naka-store na signing secret',
'Shopify_No_Signing_Secret_Desc' => 'Maaaring gumawa ng mga subscription nang wala nito, pero tatanggihan ang bawat delivery hanggang ma-save ang API secret key ng app sa store na ito (sakop na ito ng client secret ng isang Dev Dashboard app).',
'Shopify_Register_In_Shopify' => 'I-register sa Shopify',
