'Shopify_Could_Not_Read_Hooks' => 'Hindi mabasa ang mga webhook ng shop na ito',
'Shopify_Hooks_Partial' => '{created} nagawa, {failed} nabigo — tingnan ang mga log',
'Shopify_Subs_Created' => '{n} subscription ang nagawa',
'Shopify_Subs_Created_Removed' => '{n} subscription ang nagawa, {removed} ang naalis',
'Shopify_Already_Subscribed' => 'Naka-subscribe na sa lahat ng kailangan ng store na ito',
'Shopify_Could_Not_Register' => 'Hindi ma-register ang mga webhook',
'Shopify_Sub_Removed' => 'Naalis ang subscription',
'Shopify_Could_Not_Remove_Sub' => 'Hindi maalis ang subscription na iyon',
'Shopify_Could_Not_Load_Store' => 'Hindi ma-load ang store na ito',
'Shopify_G_Lead_Store' => 'Ano ang kailangan ng shop na ito para manatiling tugma. Lahat dito ay partikular sa store na ito — totoo ang mga path at id, kaya maaaring kopyahin nang direkta ang mga command sa server.',
'Shopify_G_Lead_Generic' => 'Paano nananatiling tugma ang isang Shopify shop sa ERP. Pumili ng store sa itaas para makita ang sarili nitong estado, o basahin ito kung ano ito — pareho ang cron line at webhook URL alinmang store ang ikonekta mo.',
'Shopify_G_Ways_Note' => 'Pinapatakbo ng karamihan ng shop ang dalawa: pinapanatiling kasalukuyan ng una ang shop minu-minuto, sinasalo ng ikalawa ang anumang nakaligtaan ng una — isang webhook na hindi dumating, isang edit na direktang ginawa sa Shopify admin, isang gabing down ang site.',
'Shopify_G_Both_Need' => 'Kailangan muna ito para sa parehong direksyon',
'Shopify_G_Credentials' => 'Mga Shopify credential',
'Shopify_G_Cred_Intro' => 'Mula Enero 2026, hindi na gumagawa ang Shopify ng mga custom app sa loob ng admin, kaya may dalawang uri ng koneksyon:',
'Shopify_G_Cred_DevDash' => '{app} (anumang shop na kinokonekta ngayon) — {path}. Ibigay ang mga Admin API scope para sa sini-sync ng store na ito, i-install ang app sa shop, pagkatapos ay kopyahin ang {clientId} at {clientSecret} mula sa Settings page ng app papunta sa {where}. Ipinagpapalit ng ERP ang mga ito para sa access token nang kusa at nire-renew ito bago mag-expire bawat 24 oras. Pumipirma rin ang client secret sa mga webhook, kaya wala nang ibang kailangan. Dapat nasa parehong Shopify organisation ang app at ang shop.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard app',
'Shopify_G_Cred_Legacy' => '{app} (ginawa sa admin bago ang 2026) — patuloy na gumagana nang walang pagbabago gamit ang {token} ({prefix}) nito at ang {secret} nito bilang webhook signing secret. Hindi ito kaparehong value ng token, at ang pagbabaligtad sa mga ito ang karaniwang dahilan kung bakit tinatanggihan ang mga webhook.',
'Shopify_G_Legacy_App' => 'Legacy custom app',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'naka-store',
'Shopify_G_Missing_Refused' => 'nawawala — tatanggihan ang mga delivery',
'Shopify_G_Where_Data_Desc' => '{path} Ang ERP warehouse na ang stock ay ibinebenta ng shop na ito, at ang Shopify location kung saan isinusulat ang stock na iyon. Parehong tumatangging tumakbo ang inventory sync at order import nang wala ang mga ito.',
'Shopify_G_Currently' => 'Kasalukuyan: warehouse {warehouse}, lokasyon {location}',
'Shopify_G_Not_Set_Lower' => 'hindi nakatakda',
'Shopify_G_Ready' => 'handa',
'Shopify_G_Incomplete' => 'hindi kumpleto',
'Shopify_G_Manual_Syncs' => 'Mga sync na sinisimulan mo nang mano-mano',
'Shopify_G_Manual_Desc' => 'Ang sync na sinimulan mula sa {centre} ay agad na sumasagot at tumatakbo sa background, sa maiikling bahagi na bawat isa ay nagpapatuloy mula sa huminto ang nauna. Hindi kailanman napuputol sa gitna ang malaking catalogue ng hosting na nagtatapos sa mahahabang web request (LiteSpeed, nginx, load balancer), at hindi ito pinapahinto ng pagsara ng page. Ang worker para doon ay isa pang cron line:',
'Shopify_G_Cron_Copied' => 'Nakopya ang cron line',
'Shopify_G_Manual_Note' => 'Kung wala ito, natatapos pa rin ang sync, pero habang nakabukas lang ang Sync Centre page: kapag walang worker na kumuha sa run sa loob ng ilang segundo, ang page mismo ang magpapatuloy dito, isang maikling request bawat pagkakataon. Sa Windows, gamitin ang Task Scheduler bawat minuto: program {program}, mga argument {args}, sinimulan sa {dir}.',
'Shopify_G_Then_Pick' => 'Pagkatapos ay piliin kung paano ito mananatiling tugma',
'Shopify_G_Right_Away' => 'Agad-agad',
'Shopify_G_Stock_Live' => 'live ang stock',
'Shopify_G_Stock_Not_Live' => 'hindi live ang stock',
'Shopify_G_Realtime_Lead' => 'Ipinapadala ang bawat pagbabago habang nangyayari, sa loob ng ilang segundo. Dalawang bahagi, at magkahiwalay na switch ang mga ito: ang {webhooks} ay nagpapasok ng sariling event ng shop, at ang {push} ay naglalabas ng stock.',
'Shopify_G_Webhooks_Lower' => 'mga webhook',
'Shopify_G_Instant_Push_Lower' => 'instant stock push',
'Shopify_G_Webhooks_In' => 'Mga Webhook — ang shop → ang ERP',
'Shopify_G_Webhooks_Desc' => 'Mga order, pagbabago ng order status, at mga edit ng produkto, customer at stock na ginawa sa Shopify. Buksan ang store at pindutin ang {button} sa {tab} nito — ligtas pindutin nang dalawang beses. Nagpo-post ang Shopify sa:',
'Shopify_G_Webhooks_Tab' => 'Webhooks tab',
'Shopify_G_Webhooks_Note' => 'Dapat maaabot mula sa internet ang address sa pamamagitan ng HTTPS — hindi maghahatid ang Shopify sa {localhost} o sa {test} na domain. Isang beses lang naitatala ang bawat delivery, kaya hindi makakagawa ng duplicate na order ang mga retry ng Shopify, at maaaring i-replay ang nabigo. Tinatanggihan ang mga delivery hanggang ma-store ang signing secret mula sa hakbang 1.',
'Shopify_G_Instant_Out' => 'Instant stock push — ang ERP → ang shop',
'Shopify_G_Setting_Missed' => 'Ito ang setting na madalas makaligtaan',
'Shopify_G_Pos_Not_Auto' => 'Ang POS sale ay {not} umaabot sa Shopify nang kusa. Kapag naka-off, malalaman lang ng shop sa susunod na Inventory push step — at sa panahong iyon maaari itong magbenta ng unit na naibenta mo na sa till.',
'Shopify_G_Not' => 'Hindi',
'Shopify_G_Tick_Push' => 'I-tick ang {setting} sa {where}. Iyon na ang buong setup — walang worker, walang cron. Bawat benta, return at adjustment ay magpapadala ng push ng mga produktong iyon lang, pagkatapos ma-save ang benta, at ang benta na may dalawampung linya ay isang push lang, hindi dalawampu. Hindi kailanman naghihintay ang till dito.',
'Shopify_G_This_Store' => 'Ang store na ito:',
'Shopify_G_Push_On' => 'on — pinu-push ang stock kapag nagbago',
'Shopify_G_Push_Off' => 'off — ayon sa iskedyul lang ang stock',
'Shopify_G_Push_Note' => 'Ang mga produktong may Shopify mapping na lang, at ang mga paggalaw sa warehouse ng store na ito lang, ang pinu-push. Ang mga bulk operation — pag-delete ng produkto, pag-reset ng warehouse — ay sumusulat ng stock nang hindi nagpapalabas ng event, na isang dahilan para panatilihin din ang naka-iskedyul na inventory step.',
'Shopify_G_Nothing_Install' => 'Wala nang ibang i-install',
'Shopify_G_No_Worker_Note' => 'Hindi kailangan ng alinmang bahagi ng queue worker o cron entry. Ang papasok na webhook ay hinahawakan sa request na ginagawa ng Shopify; ang palabas na stock push ay tumatakbo sa parehong proseso na nagsilbi sa benta, {after} maibalik ang response — kaya hindi kailanman naghihintay ang till sa Shopify, at ang shop na tumigil sumagot ay sinusukuan pagkalipas ng sampung segundo at iniiwan sa susunod na naka-iskedyul na inventory push.',
'Shopify_G_After' => 'pagkatapos',
'Shopify_G_Artisan_Note' => 'Isang eksepsiyon: ang pagbabago ng stock na ginawa ng artisan command ay walang response na susundan, kaya ipinipila ito sa {queue} sa halip. Kung gusto mong mailabas din agad ang mga iyon, patakbuhin ang queue na iyon:',
'Shopify_G_On_Schedule' => 'Ayon sa iskedyul',
'Shopify_G_On_Lower' => 'naka-on',
'Shopify_G_Off_Lower' => 'naka-off',
'Shopify_G_Scheduled_Lead' => 'Muling sinusuri ang lahat paminsan-minsan, sa parehong direksyon. Mas mabagal kaysa real time, pero ito ang naglalabas ng stock sa mga shop na hindi gumagamit ng instant push, ang sumasalo sa nakaligtaang webhook, at ang tanging paraan para ilipat ang buong catalogue.',
'Shopify_G_Cron_Entry' => 'Ang cron entry',
'Shopify_G_Cron_Entry_Desc' => 'Walang naka-iskedyul na tatakbo kung wala ito. Isang linya, para sa module na ito lang — idagdag ito sa tabi ng anumang iba pang pinili mong i-iskedyul:',
'Shopify_G_Cron_Note' => 'Bawat limang minuto ang pinakamaliit na resolution na magagamit ng plano, dahil limang minuto ang pinakamaikling step interval. Ang mas malaking entry ay nagiging minimum — sa {example}, ang hakbang na nakatakda sa 5 minuto ay tatakbo bawat 15. Sa Windows, gamitin ang Task Scheduler: program {program}, mga argument {args}, sinimulan sa {dir}.',
'Shopify_G_Switch_On_Plan' => 'I-on ito, at piliin ang plano',
'Shopify_G_Plan_Desc' => '{where} Ang switch ang nagpapasya kung maaaring kumilos ang cron; ang plano ang nagpapasya kung ano ang gagawin nito. Ang {step} ay isang entity sa isang direksyon na may sariling interval — {first}, {second}. Ginagamit ang default na interval ng anumang hakbang na iniwang blangko ang sariling kahon.',
'Shopify_G_Step_Lower' => 'hakbang',
'Shopify_G_Plan_Note' => 'Iwanang blangko ang plano at magpu-pull ang store ng mga order at magpu-push ng stock sa default na interval, na siyang gusto ng karamihan ng shop. Pull-only ang mga order: sa Shopify naglalagay ng order ang customer.',
'Shopify_G_Schedule_On' => 'naka-on ang iskedyul',
'Shopify_G_Schedule_Off' => 'naka-off ang iskedyul — manual lang',
'Shopify_G_When_Step_Runs' => 'Kailan talaga tumatakbo ang isang hakbang',
'Shopify_G_When_Note' => 'Due ang isang hakbang kapag ang parehong hakbang ay huling {started} nang mas matagal kaysa sa interval nito, ayon sa kasaysayan ng run. Kaya ang sync na sinimulan mo nang mano-mano ay nag-aantala sa susunod na awtomatiko, at ang hakbang na patuloy na nabibigo ay inuulit ayon sa interval nito sa halip na bawat tick. Ipinapakita ng Overview ng store ang huling run ng bawat hakbang, ang susunod na due time, at ang dahilan kung bakit ito naka-block kapag ganoon. Patakbuhin nang mano-mano ang unang catalogue push — gamit muna ang {dryRun} — bago ito ilagay sa iskedyul.',
'Shopify_G_Started_Lower' => 'nagsimula',
'Shopify_G_Where_Setting' => 'Kung saan matatagpuan ang bawat setting',
'Shopify_G_Where_Setting_Note' => 'Lahat ng ito ay nasa isang kasalukuyang store: {path}, pagkatapos ay ang lapis (o {edit} sa sariling page ng store).',
'Shopify_G_Product_Images' => 'Mga larawan ng produkto',
'Shopify_G_Img_1' => 'Lumalabas ang mga larawan kasama ng produkto sa isang {push} — una ang pangunahing larawan, pagkatapos ang gallery, pagkatapos ay isa kada variant na may sariling larawan, hanggang limampu.',
'Shopify_G_Products_Push' => 'products push',
'Shopify_G_Img_2' => 'Ina-upload ang larawan ng variant kasama ng produkto at pagkatapos ay {assigned}, na siyang paraan ng Shopify: tumuturo ang variant sa isa sa mga larawan ng produkto. Ang variant na muling gumagamit ng pangunahing larawan ay hindi ito ina-upload nang dalawang beses.',
'Shopify_G_Assigned' => 'ina-assign sa variant na iyon',
'Shopify_G_Img_3' => 'Ang larawang naka-store bilang file ay {uploaded} sa Shopify, hindi naka-link, kaya gumagana ito kahit hindi maabot ang installation na ito mula sa internet. Ang larawang idinagdag bilang pasted link ay ibinibigay sa Shopify bilang URL na iyon, na dapat maaabot ng publiko.',
