'Cr_Guide_Step_Account' => 'Magdagdag ng courier account',
'Cr_Guide_Step_Account_Help' => 'Piliin ang iyong courier at i-paste ang mga API key mula sa dashboard nito. Puwede ang ilang account, halimbawa isa bawat warehouse.',
