'Cr_Guide_Step_Webhook' => 'I-register ang webhook URL',
'Cr_Guide_Step_Webhook_Help' => 'Kailangan ng mga courier na nagpu-push ng update ang webhook URL ng account (nakalista sa ibaba) para agad magbago ang mga status. Ang iba ay sinusuri ayon sa schedule.',
'Cr_Guide_Step_Cod' => 'Piliin kung saan mapupunta ang mga COD payout',
'Cr_Guide_Step_Cod_Help' => 'Sa Courier Settings, piliin ang account kung saan ire-record ang mga COD payout, at kung paano hahawakan ang mga ibinalik na parcel at singil ng courier.',
'Cr_Guide_Step_Notify' => 'Abisuhan ang iyong mga customer',
