'Cr_Guide_You_Need' => 'Kailangan mo',
'Cr_Guide_No_Keys' => 'Walang API key: walang kailangang i-connect.',
'Cr_Guide_Good_To_Know' => 'Mabuting malaman',
'Cr_Guide_Webhooks' => 'Mga webhook address',
'Cr_Guide_How' => 'Paano ito i-register',
'Cr_Guide_How_It_Works' => 'Paano ito gumagana',
'Cr_Guide_Meaning' => 'Kahulugan',
'Cr_Guide_T_Statuses' => 'Mga status',
'Cr_Guide_Statuses_Note' => 'Pasulong lamang gumagalaw ang mga status, kaya hindi kailanman maibabalik ng huling update ang isang parcel. Ang na-deliver na parcel ay maaari pa ring i-report bilang pabalik o naibalik.',
'Cr_Guide_S_booked' => 'Nasa courier na ang order; wala pang kumukuha nito. Ngayon lamang maaaring kanselahin ang booking.',
'Cr_Guide_S_picked_up' => 'Nakuha na ng courier ang parcel.',
'Cr_Guide_S_in_transit' => 'Gumagalaw sa pagitan ng mga hub, nasa customs o naka-hold.',
'Cr_Guide_S_out_for_delivery' => 'Nasa rider ngayong araw.',
'Cr_Guide_S_failed_attempt' => 'Wala sa bahay, tinanggihan o maling address. Susubok muli ang courier o ibabalik ito.',
'Cr_Guide_S_delivered' => 'Naibigay na sa customer. Ang halaga ng COD ay nagiging nakolekta ng courier.',
'Cr_Guide_S_returning' => 'Pabalik na sa iyo.',
'Cr_Guide_S_returned' => 'Nakabalik na sa iyo: naghihintay ito sa Returns para suriin, o awtomatikong ibinabalik sa stock.',
'Cr_Guide_S_cancelled' => 'Kinansela ang booking.',
'Cr_Guide_T_Booking' => 'Pag-book ng mga order',
'Cr_Guide_B_Booking' => 'Pinupunan ng Send to courier ang form mula sa benta: tatanggap, address, ang natitirang halagang dapat bayaran bilang COD, at ang timbang ng mga produkto. Ang mga courier na may sariling listahan ng lungsod ay nagpapakita ng picker, at naaalala ang iyong pinili para sa lungsod na iyon. Ang mga aggregator, DHL, FedEx, UPS at Lalamove ay nag-aalok ng Compare rates: pumili ng presyo at bibilhin ito ng Book. Maaaring i-book nang sabay-sabay ang ilang benta mula sa listahan ng benta.',
'Cr_Guide_T_Cod' => 'Cash on delivery',
'Cr_Guide_B_Cod' => 'Ang COD parcel ay napupunta mula Not collected patungong Collected by courier (sa pag-deliver) hanggang Paid out to you. Ang mga courier na nagre-report ng payout ay sila na ang naglilipat ng huling hakbang; para sa iba, gamitin ang Update COD. Kapag may napiling account sa Courier Settings, nire-record ang payout bilang bayad sa benta. Maaaring i-save bilang gastos ang mga singil ng courier kapag tapos na ang parcel.',
'Cr_Guide_T_Returns' => 'Mga ibinalik na parcel',
'Cr_Guide_B_Returns' => 'Bilang default, naghihintay ang ibinalik na parcel sa Courier Shipments sa ilalim ng Returns to review. Gumagawa ang Restock ng sale return para sa buong order at ibinabalik ang mga item sa stock; walang ibinabalik ang Dismiss, para sa mga sira o nawawalang parcel. Maaaring itakda sa Courier Settings na awtomatikong mag-restock.',
'Cr_Guide_T_Customers' => 'Mga mensahe sa customer at tracking page',
'Cr_Guide_B_Customers' => 'Ang mga customer notification sa Courier Settings ay nagpapadala ng SMS, email o WhatsApp sa mga status na mamarkahan mo, isang beses bawat parcel, gamit ang sarili mong teksto. Ang tracking page sa iyong online na tindahan ay nagpapahintulot sa mga customer na sundan ang parcel gamit ang tracking number, o order number at telepono. Ang mga customer na madalas magbalik ng parcel ay nakakakuha ng return-risk badge kapag nag-book ka.',
'Cr_Guide_T_Labels' => 'Mga label',
'Cr_Guide_B_Labels' => 'Ibinibigay ng Print label ang sariling label ng courier kapag naglalabas ito ng isa (PDF, link o larawan), kung hindi ay Stocky label na may tracking barcode at halagang kokolektahin. Payagan ang mga pop-up para sa site na ito para makapag-print. Isang beses lang ibinibigay ng DHL, FedEx at UPS ang kanilang label, sa booking, at itinatago ito ng Stocky para sa muling pag-print.',
'Cr_Guide_T_Faq' => 'Pag-troubleshoot',
'Cr_Guide_Q_Test' => 'Pumapalya ang Test connection',
'Cr_Guide_A_Test' => 'Ang mga test-mode key ay para sa Test mode at ang mga live key ay para sa Live; magkaiba ang mga ito. Buksan ang Courier logs at basahin ang sagot ng courier para sa eksaktong dahilan.',
'Cr_Guide_Q_City' => 'Tinatanggihan ng courier ang lungsod o address',
'Cr_Guide_A_City' => 'Piliin ang lungsod mula sa listahan ng lungsod ng courier sa booking form; sariling pangalan lang nila ang tinatanggap ng mga courier. Ang mga courier na gumagamit ng postal address ay nangangailangan din ng state, postal code at dalawang-letrang bansa.',
'Cr_Guide_Q_Webhook' => 'Hindi kusang nagbabago ang mga status',
'Cr_Guide_A_Webhook' => 'Para sa mga courier na nagpu-push, tiyaking naka-register ang webhook URL sa courier: ipinapakita ng Courier logs ang bawat natanggap na update, o kung bakit tinanggihan ang isa (halimbawa, maling secret). Ang ibang courier ay sinusuri ayon sa schedule sa Courier Settings, at agad nagtatanong ang Check status now.',
'Cr_Guide_Q_Stuck' => 'May status check error ang isang shipment',
'Cr_Guide_A_Stuck' => 'Tinanggihan ng courier ang mga huling pag-check; nasa shipment at sa Courier logs ang dahilan. Pagkatapos ng paulit-ulit na pagpalya, hindi na awtomatikong sinusuri ang shipment: ayusin ang sanhi, pagkatapos ay gamitin ang Check status now.',
'Cr_Guide_Q_Label' => 'Walang nagbubukas kapag nagpi-print ng label',
'Cr_Guide_A_Label' => 'Hinarang ng iyong browser ang pop-up. Payagan ang mga pop-up para sa site na ito at subukang muli.',
'Cr_Guide_Q_Cod' => 'Hindi na-record sa benta ang isang COD payout',
'Cr_Guide_A_Cod' => 'Sa Courier Settings, kailangang naka-on ang switch ng cash on delivery at may napiling account. Kung walang account, minamarkahan lamang na paid out ang mga payout.',
