'Tfa_Guide_Codes_Text' => 'Pagkatapos ng setup, ipinapakita nang isang beses ang 8 recovery code. Bawat isa ay pumapalit sa code ng telepono nang isang beses — para sa nawala, nasira o na-reset na telepono. I-download o kopyahin ang mga ito at itago sa ligtas na lugar, malayo sa telepono.',
'Tfa_Guide_Codes_Note' => 'Paubos na? Pinapalitan ng "New recovery codes" sa profile ang buong set; hindi na gagana ang mga luma.',
'Tfa_Guide_Signin_Title' => 'Pag-sign in',
'Tfa_Guide_Signin_Text' => 'Pagkatapos ng email at password, hihingin ng login page ang kasalukuyang code mula sa app. Nagbabago ang mga code bawat 30 segundo at isang beses lang gumagana ang bawat isa.',
'Tfa_Guide_Signin_Trust' => 'Kapag minarkahan ang "Huwag nang magtanong muli sa device na ito", lalaktawan ang code sa browser na iyon sa loob ng :days araw.',
'Tfa_Guide_Signin_Recovery' => 'Walang telepono sa kamay? I-click ang "Use a recovery code" at i-type ang isa sa mga na-save na code.',
'Tfa_Guide_Admin_Title' => 'Para sa mga administrator',
'Tfa_Guide_Require_Title' => 'Gawin itong mandatory',
'Tfa_Guide_Require_Text' => 'I-on ang "Require two-factor authentication" sa card na ito, pagkatapos ay piliin ang mga role na kailangang gumamit nito — o iwanang blangko ang listahan para sa bawat user. I-click ang Submit para i-save.',
'Tfa_Guide_Require_Next' => 'Walang masa-sign out. Ang mga user na wala pang 2FA ay gagabayan sa setup sa login page sa susunod nilang pag-sign in, bago sila makapasok, at doon nila makikita ang kanilang mga recovery code.',
'Tfa_Guide_Require_Note' => 'Hindi ito maaaring i-off mula sa profile ng mga user na kinakailangan nito.',
'Tfa_Guide_Trust_Title' => 'Mga pinagkakatiwalaang device',
'Tfa_Guide_Trust_Text' => 'Itinatakda ng "Remember trusted devices" kung gaano katagal maaaring laktawan ng browser ang code pagkatapos ng matagumpay na pag-sign in. Piliin ang "Always ask for a code" para sa mga shared o pampublikong computer gaya ng POS sa tindahan.',
'Tfa_Guide_Trust_Note' => 'Ang pagbaba ng bilang ay nagpapaikli rin sa mga device na pinagkakatiwalaan na; ang pag-off o pag-reset ng 2FA ay kinakalimutan silang lahat.',
'Tfa_Guide_Lost_Title' => 'Nawalang telepono at walang recovery code',
'Tfa_Guide_Lost_Text' => 'Sa Users page, ang mga user na may 2FA ay nagpapakita ng "On" sa 2FA column. Nire-reset ito ng shield button sa Actions: magsa-sign in ang user gamit lamang ang password at ise-set up muli ang app (o hihilingin sa kanya, kung kinakailangan ito).',
'Tfa_Guide_Lost_Warn' => 'Kumpirmahin kung sino ang humihiling bago mag-reset — inaalis ng reset ang proteksyong ibinibigay ng 2FA sa account na iyon.',
'Tfa_Guide_Open_Users' => 'Buksan ang Users',
'Tfa_Guide_Mobile_Title' => 'Mobile app at API',
'Tfa_Guide_Mobile_Text' => 'Humihingi rin ng parehong code ang mobile app at ang API token endpoint. Kung kinakailangan ang 2FA para sa isang user na hindi pa ito nase-set up, kailangan muna niyang mag-sign in sa web nang isang beses para gawin ito.',
'Tfa_Guide_Protect_Title' => 'Built-in na proteksyon',
'Tfa_Guide_Protect_1' => '5 maling code ay haharang sa paglalagay ng code para sa user na iyon sa loob ng 15 minuto, anuman ang lockout settings sa itaas.',
'Tfa_Guide_Protect_2' => 'Isang beses lang gumagana ang bawat code at bawat recovery code.',
'Tfa_Guide_Protect_3' => 'Kapag naka-on ang "Record sign-in activity", lumalabas ang mga maling code sa Sign-in activity list bilang "Wrong 2FA code".',
'Tfa_Guide_Trouble_Title' => 'Pag-troubleshoot',
'Tfa_Guide_Faq_Clock_Q' => '“Hindi valid ang code na iyan” kahit bagong code',
'Tfa_Guide_Faq_Clock_A' => 'Malamang mali ang orasan ng telepono. Nakadepende sa oras ang mga code: itakda sa awtomatiko (network time) ang petsa at oras ng telepono, pagkatapos ay subukan ang susunod na code.',
'Tfa_Guide_Faq_Phone_Q' => 'Paglipat sa bagong telepono',
'Tfa_Guide_Faq_Phone_A' => 'Gamitin ang sariling transfer feature ng authenticator app, o i-off ang 2FA sa profile at i-on muli gamit ang bagong telepono (kung kinakailangan ito, hilingin sa admin na i-reset ito).',
'Tfa_Guide_Faq_Locked_Q' => '“Masyadong maraming invalid na code”',
'Tfa_Guide_Faq_Locked_A' => 'Hintayin ang ipinapakitang oras (hanggang 15 minuto), o ipa-reset sa admin ang 2FA ng user.',
'Tfa_Guide_Faq_Key_Q' => 'Walang makapag-sign in na may 2FA pagkatapos ilipat ang server',
'Tfa_Guide_Faq_Key_A' => 'Naka-encrypt ang mga 2FA secret gamit ang APP_KEY sa .env file. Panatilihin ang parehong APP_KEY kapag inililipat o nire-restore ang app; kung nagbago ito, kailangang i-reset ng admin na walang 2FA ang mga apektadong user.',
'Tfa_Guide_Button' => 'Gabay',
'Tfa_Guide_Title' => 'Gabay sa two-factor authentication',
'Sec_2fa_Pending' => ':count pa ang kailangang mag-set up nito',
'Sec_2fa_See_Who' => 'Tingnan kung sino',
'Sec_2fa_Grace_Off' => 'Wala — i-set up sa susunod na pag-sign in',
'Sec_2fa_Applied' => ':count user ang na-sign out.',
'Tfa_Guide_Rollout_Title' => 'Ipatupad ito sa bawat user',
'Tfa_Guide_Rollout_1' => 'I-on muna ito para sa sarili mong account (Profile), para alam mo ang mga hakbang.',
'Tfa_Guide_Rollout_2' => 'Sabihin sa iyong team kung aling app ang i-install at na isang minuto lang ang setup sa pag-sign in.',
'Tfa_Guide_Rollout_3' => 'I-on ang "Require two-factor authentication", iwanang blangko ang "Required for" (= bawat user), at opsyonal na pumili ng grace period. I-click ang Submit.',
'Tfa_Guide_Rollout_4' => 'I-click ang "Sign out users without 2FA" para ang mga naka-sign in na ay mag-set up nito ngayon sa halip na sa susunod na pag-sign in. Mananatili kang naka-sign in.',
'Tfa_Guide_Rollout_5' => 'Subaybayan ang progreso gamit ang counter sa card na ito, o ang "Needs setup" filter sa Users page.',
'Tfa_Guide_Rollout_Note' => 'Kapag may grace period, ipinapakita ng setup screen ang “Remind me later” hanggang sa deadline; pagkatapos nito, kailangan ang setup para makapag-sign in.',
'Tfa_Guide_Customers_Title' => 'Mga customer account (tindahan at client portal)',
'Tfa_Guide_Customers_Text' => 'Maaari ring protektahan ng mga customer ang sarili nilang account. Opsyonal ito para sa bawat customer at hindi kailanman pinipilit: i-on ito sa Store Settings → Registration Access Control (online na tindahan) at Client Portal → Portal Settings (client portal).',
'Tfa_Guide_Customers_1' => 'Ino-on ito ng mga customer mula sa My Account (tindahan) o Profile (portal).',
'Tfa_Guide_Customers_2' => 'Pipili sila ng code na ipinapadala sa email — pinakamadali, walang kailangang app — o authenticator app na may mga recovery code.',
'Tfa_Guide_Customers_3' => 'Ang mga code sa email ay nangangailangan ng gumaganang mail settings (Settings → Mail Settings). Nag-e-expire ang mga ito pagkatapos ng 10 minuto.',
'Tfa_Guide_Customers_4' => 'Ang pag-off ng opsyon sa ibang pagkakataon ay humihinto sa mga bagong setup; ang mga customer na gumagamit na nito ay patuloy na tatanungin at maaaring i-off ito mismo.',
'Tfa_Required_Grace_Notice' => 'Hinihingi ng iyong administrator ang two-factor authentication. Maaari mo itong ipagpaliban sa pag-sign in hanggang :date; pagkatapos nito, kailangan na ang setup.',
'Tfa_Filter_All' => '2FA: lahat ng user',
'Tfa_Needs_Setup_Help' => 'Hinihingi ng System Settings > Security; hihilinging i-set up ito sa susunod na pag-sign in.',
