'Tfa_Filter_Pending' => 'Kailangang i-set up (kinakailangan)',
'Store_Customer_2fa' => 'Two-step verification',
'Store_Customer_2fa_Help' => 'Pinapayagan ang mga customer na protektahan ang kanilang account gamit ang code na ipinapadala sa email o mula sa authenticator app, ino-on mula sa My Account. Opsyonal para sa bawat customer.',
'Portal_2fa' => 'Two-step verification',
'Portal_2fa_Help' => 'Pinapayagan ang mga client na protektahan ang kanilang portal login gamit ang code na ipinapadala sa email o mula sa authenticator app, ino-on mula sa kanilang profile. Opsyonal para sa bawat client.',
'Two_factor_grace_notice' => 'Kinakailangan simula :date. Maaari mo itong i-set up mamaya hanggang sa petsang iyon.',
'Two_factor_remind_later' => 'Paalalahanan ako mamaya',
'Sec_2fa_Grace' => 'Grace period',
'Sec_2fa_Grace_Help' => 'Pinapayagan ang mga user na piliin ang “Remind me later” sa setup screen hanggang sa deadline, para walang mapahinto sa gitna ng shift. Binibilang mula nang i-on ang requirement.',
'Sec_2fa_Grace_Ends' => 'Magiging mandatory ang setup sa :date.',
'Sec_2fa_Apply' => 'Ilapat ngayon',
'Sec_2fa_Apply_Help' => 'Ang mga naka-sign in na ay tatanungin lamang sa susunod nilang pag-sign in, na maaaring ilang buwan pa kapag may “Remember me”. Isa-sign out nito ang lahat ng kailangang mag-set up ng 2FA at hindi pa nakakagawa, sa bawat device, para ma-set up nila ito pagbalik nila sa pag-sign in. Mananatili kang naka-sign in.',
'Sec_2fa_Apply_Confirm' => 'I-sign out ang :count user ngayon?',
'Sec_2fa_Apply_Ok' => 'I-sign out sila',
